int open_url(AVFormatContext *s, AVIOContext **pb, const char *url, AVDictionary *opts, AVDictionary *opts2, int *is_http) {
    int ret;
    AVDictionary *temp_opts = NULL;

    if (!url || !is_http) {
        return AVERROR(EINVAL);
    }

    *is_http = 0;

    // Copy options dictionaries to avoid modifying the input ones
    if (opts) {
        av_dict_copy(&temp_opts, opts, 0);
    }

    if (opts2) {
        av_dict_copy(&temp_opts, opts2, AV_DICT_APPEND);
    }

    // Check the protocol
    const char *protocol = avio_find_protocol_name(url);
    if (!protocol) {
        av_dict_free(&temp_opts);
        return AVERROR(EINVAL);
    }

    // Determine if the protocol is HTTP or HTTPS
    if (!strcmp(protocol, "http") || !strcmp(protocol, "https")) {
        *is_http = 1;
    } else if (strcmp(protocol, "file")) {
        av_dict_free(&temp_opts);
        return AVERROR(EINVAL);
    }

    // Open the URL with options
    ret = avio_open2(pb, url, AVIO_FLAG_READ, NULL, temp_opts);
    if (ret < 0) {
        av_dict_free(&temp_opts);
        return ret;
    }

    av_dict_free(&temp_opts);
    return 0;
}

